import 'bootstrap/dist/css/bootstrap.min.css';
import React, { useEffect, useState } from "react";
import './Profile.css'; // Import the new CSS file

export default function Profile() {
  const [profile, setProfile] = useState({
    fullName: "",
    email: "",
    phone: "",
    role: "Software Engineer", // static
    bio: ""
  });

  const [loading, setLoading] = useState(true);
  const [message, setMessage] = useState("");

  // Fetch logged-in user data
  useEffect(() => {
    const fetchProfile = async () => {
      const token = localStorage.getItem("token"); // JWT token
      if (!token) {
        setLoading(false);
        return;
      }

      try {
        const response = await fetch("http://127.0.0.1:8000/api/users/me/", {
          headers: { Authorization: `Bearer ${token}` }
        });
        if (response.ok) {
          const data = await response.json();
          setProfile({
            fullName: `${data.first_name || ""} ${data.last_name || ""}`,
            email: data.email || "",
            phone: data.profile?.phone || "",
            bio: data.profile?.bio || "",
            role: "Software Engineer" // Assuming this remains static or fetched if needed
          });
        } else {
          console.error("Failed to fetch profile");
          setMessage("Failed to load profile data.");
        }
      } catch (err) {
        console.error("Network error during profile fetch:", err);
        setMessage("Network error. Could not load profile.");
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, []);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setProfile((prev) => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setMessage(""); // Clear previous messages
    const token = localStorage.getItem("token");
    if (!token) {
      setMessage("Authentication required to update profile.");
      return;
    }

    const [first_name, ...rest] = profile.fullName.split(" ");
    const last_name = rest.join(" ");

    try {
      const response = await fetch(`http://127.0.0.1:8000/api/users/me/`, {
        method: "PUT", // or PATCH if you want partial update
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify({
          first_name,
          last_name,
          email: profile.email,
          profile: { // Ensure 'profile' object is sent for nested fields
            phone: profile.phone,
            bio: profile.bio
          }
        })
      });

      if (response.ok) {
        setMessage("Profile updated successfully!");
      } else {
        const data = await response.json();
        console.error("Update error:", data);
        setMessage(`Failed to update profile: ${data.detail || JSON.stringify(data)}`);
      }
    } catch (err) {
      console.error("Network error during profile update:", err);
      setMessage("Network error. Please try again later.");
    }
  };

  if (loading) {
    return (
      <div className="profile-container">
        <div className="loading-state">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">Loading...</span>
          </div>
          <p>Loading profile...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="profile-container">
      <div className="profile-header">
        <h1 className="profile-title">My Profile</h1>
        <p className="profile-subtitle">Manage your personal information</p>
      </div>

      <div className="profile-card">
        <form onSubmit={handleSubmit}>
          <div className="form-grid">
            <div className="form-group">
              <label htmlFor="fullName" className="form-label">Full Name</label>
              <input
                type="text"
                id="fullName"
                className="form-control"
                name="fullName"
                value={profile.fullName}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="email" className="form-label">Email Address</label>
              <input
                type="email"
                id="email"
                className="form-control"
                name="email"
                value={profile.email}
                onChange={handleChange}
                required
              />
            </div>

            <div className="form-group">
              <label htmlFor="phone" className="form-label">Phone Number</label>
              <input
                type="tel"
                id="phone"
                className="form-control"
                name="phone"
                value={profile.phone}
                onChange={handleChange}
              />
            </div>

            <div className="form-group">
              <label htmlFor="role" className="form-label">Role</label>
              <input
                type="text"
                id="role"
                className="form-control"
                value={profile.role}
                readOnly
              />
            </div>
          </div>

          <div className="form-group">
            <label htmlFor="bio" className="form-label">Bio</label>
            <textarea
              id="bio"
              className="form-control"
              name="bio"
              rows="3"
              value={profile.bio}
              onChange={handleChange}
            ></textarea>
          </div>

          
        </form>

        {message && (
          <p className={`profile-message ${message.includes("success") ? "text-success" : "text-danger"}`}>
            {message}
          </p>
        )}
      </div>
    </div>
  );
}
